{
  "doc_type": "Notice d'information",
  "audience": "Élèves de 10e année du secondaire",
  "core": {
    "what": {
      "text": "Semaine de stage d'observation du 15 au 19 mars 2027 pour toutes les classes de 10e année.",
      "segment_ids": ["s0003"]
    },
    "must_do": {
      "text": "Trouver une place de stage, remettre l'attestation signée avant le 19 février 2027, informer l'enseignant si aucune place avant le 5 février 2027, réaliser le stage, remettre le rapport avant le 2 avril 2027.",
      "segment_ids": ["s0007", "s0008", "s0009", "s0022"]
    },
    "deadline": {
      "text": "Attestation : 19 février 2027 ; Absence de place : 5 février 2027 ; Rapport : 2 avril 2027.",
      "segment_ids": ["s0008", "s0009", "s0022"]
    },
    "cost": {
      "text": "Frais de repas et de déplacement à la charge des parents, remboursement maximum 30 CHF par semaine sur justificatifs.",
      "segment_ids": ["s0017", "s0018"]
    },
    "contact": {
      "text": "Enseignant titulaire, secrétariat (tél. 022 123 45 70, email secretariat@es-exempleville.example), office d'orientation (Rue de la Gare 10, 1999 Exempleville).",
      "segment_ids": ["s0024", "s0014", "s0010"]
    }
  },
  "facts": [
    {
      "id": "f01",
      "kind": "deadline",
      "text": "L'attestation remplie doit être remise au plus tard le 19 février 2027.",
      "value_norm": "2027-02-19",
      "segment_ids": ["s0008"],
      "must_keep": true
    },
    {
      "id": "f02",
      "kind": "deadline",
      "text": "Si aucune place n'est trouvée, il faut informer l'enseignant avant le 5 février 2027.",
      "value_norm": "2027-02-05",
      "segment_ids": ["s0009"],
      "must_keep": true
    },
    {
      "id": "f03",
      "kind": "deadline",
      "text": "Le rapport de stage doit être remis au plus tard le 2 avril 2027.",
      "value_norm": "2027-04-02",
      "segment_ids": ["s0022"],
      "must_keep": true
    },
    {
      "id": "f04",
      "kind": "amount",
      "text": "Remboursement maximum de 30 CHF par semaine pour les transports publics sur justificatifs.",
      "value_norm": "30",
      "segment_ids": ["s0018"],
      "must_keep": true
    },
    {
      "id": "f05",
      "kind": "obligation",
      "text": "La participation à la semaine de stage est obligatoire pour tous les élèves.",
      "value_norm": null,
      "segment_ids": ["s0006"],
      "must_keep": true
    },
    {
      "id": "f06",
      "kind": "obligation",
      "text": "Chaque élève doit chercher sa place de stage de manière autonome.",
      "value_norm": null,
      "segment_ids": ["s0007"],
      "must_keep": true
    },
    {
      "id": "f07",
      "kind": "obligation",
      "text": "L'attestation signée par l'entreprise doit être remise à l'enseignant titulaire.",
      "value_norm": null,
      "segment_ids": ["s0008"],
      "must_keep": true
    },
    {
      "id": "f08",
      "kind": "obligation",
      "text": "Un certificat médical est exigé pour toute absence de plus de 2 jours.",
      "value_norm": null,
      "segment_ids": ["s0015"],
      "must_keep": true
    },
    {
      "id": "f09",
      "kind": "condition",
      "text": "La durée quotidienne du travail pendant le stage ne doit pas excéder 8 heures.",
      "value_norm": null,
      "segment_ids": ["s0013"],
      "must_keep": true
    },
    {
      "id": "f10",
      "kind": "contact",
      "text": "Office d'orientation scolaire et professionnelle, Rue de la Gare 10, 1999 Exempleville.",
      "value_norm": null,
      "segment_ids": ["s0010"],
      "must_keep": true
    },
    {
      "id": "f11",
      "kind": "contact",
      "text": "Téléphone du secrétariat : 022 123 45 70.",
      "value_norm": "0221234570",
      "segment_ids": ["s0014"],
      "must_keep": true
    },
    {
      "id": "f12",
      "kind": "contact",
      "text": "Adresse e‑mail du secrétariat : secretariat@es-exempleville.example.",
      "value_norm": "secretariat@es-exempleville.example",
      "segment_ids": ["s0024"],
      "must_keep": true
    },
    {
      "id": "f13",
      "kind": "contact",
      "text": "Site web avec modèles et informations : www.es-exempleville.example/orientation.",
      "value_norm": "www.es-exempleville.example/orientation",
      "segment_ids": ["s0025"],
      "must_keep": true
    },
    {
      "id": "f14",
      "kind": "right",
      "text": "L'établissement assure les élèves contre les accidents pendant le stage.",
      "value_norm": null,
      "segment_ids": ["s0019"],
      "must_keep": true
    }
  ],
  "hard_terms": [
    {
      "term": "office d'orientation scolaire et professionnelle",
      "explanation": "Service de la commune qui aide les jeunes à choisir une formation ou un emploi. Il propose des conseils et des recherches de stage.",
      "segment_ids": ["s0010"]
    },
    {
      "term": "secrétariat",
      "explanation": "Bureau administratif de l'école où l'on peut appeler ou envoyer des e‑mails. Il gère les dossiers et les informations pour les élèves.",
      "segment_ids": ["s0014", "s0024"]
    },
    {
      "term": "attestation",
      "explanation": "Document signé par l'entreprise qui confirme que l'élève a effectué le stage. Il doit être remis à l'enseignant.",
      "segment_ids": ["s0008"]
    },
    {
      "term": "journal de stage",
      "explanation": "Carnet où l'élève note chaque jour ce qu'il a fait pendant le stage. Il fait partie du dossier d'orientation.",
      "segment_ids": ["s0021"]
    },
    {
      "term": "rapport de stage",
      "explanation": "Document final qui résume le travail effectué et inclut l'évaluation de l'entreprise. Il est remis à l'enseignant après le stage.",
      "segment_ids": ["s0022"]
    },
    {
      "term": "CHF",
      "explanation": "Abréviation du franc suisse, la monnaie de la Suisse. Le remboursement des frais de transport est exprimé en CHF.",
      "segment_ids": ["s0018"]
    }
  ],
  "omit_candidates": [
    {
      "segment_ids": ["s0012"],
      "reason": "Rappel du règlement interne de l'entreprise, déjà implicite."
    },
    {
      "segment_ids": ["s0016"],
      "reason": "Information sur le bulletin scolaire, pas essentielle pour la réalisation du stage."
    }
  ]
}

{
  "repairs": [
    {
      "id": "b011",
      "texts": [
        "Tu tiens le journal de stage de ton dossier d'orientation."
      ]
    }
  ],
  "additions": [
    {
      "after": "b012",
      "texts": [
        "Le rapport de stage doit contenir l’évaluation de l’entreprise.",
        "Tu remets le rapport dans les deux semaines qui suivent la semaine de stage."
      ],
      "fact_ids": ["f20"],
      "segment_ids": ["s0022"]
    }
  ]
}

{
  "repairs": [
    {
      "id": "b004",
      "texts": [
        "L'école suspend les cours pendant cette semaine."
      ]
    },
    {
      "id": "b012.2",
      "texts": [
        "Tu remets le rapport dans les 2 semaines après la semaine de stage."
      ]
    },
    {
      "id": "b014",
      "texts": [
        "En cas de maladie ou d’accident, tu avertis l’entreprise, le secrétariat avant 7 h 30."
      ]
    },
    {
      "id": "b017",
      "texts": [
        "Qui paie les frais ?"
      ]
    },
    {
      "id": "b019",
      "texts": [
        "L’établissement rembourse les frais de transport jusqu’à 30 CHF par semaine."
      ]
    }
  ],
